/* Google Scholar citation visualization. The data file is generated by GitHub Actions. */
(async function () {
  const svg = document.getElementById('citation-svg');
  const note = document.getElementById('citation-updated');
  const tooltip = document.getElementById('citation-tooltip');
  const details = document.getElementById('citation-details');
  const ns = 'http://www.w3.org/2000/svg';
  function element(tag, attrs, text) {
    const n = document.createElementNS(ns, tag);
    Object.entries(attrs).forEach(([k, v]) => n.setAttribute(k, String(v)));
    if (text !== undefined) n.textContent = text;
    svg.appendChild(n);
    return n;
  }
  function show(group) {
    tooltip.replaceChildren();
    group.forEach(p => {
      const title = document.createElement('strong');
      title.textContent = p.title;
      tooltip.append(title);
    });
    tooltip.hidden = false;
  }
  function select(group) {
    details.replaceChildren();
    group.forEach(p => {
      const item = document.createElement('p');
      if (p.link && /^https:\/\/(scholar\.google\.com|doi\.org)\//.test(p.link)) {
        const a = document.createElement('a');
        a.href = p.link;
        a.textContent = p.title + ' ↗';
        a.target = '_blank';
        a.rel = 'noopener noreferrer';
        item.append(a);
      } else {
        item.textContent = p.title;
      }
      details.append(item);
    });
  }
  try {
    const response = await fetch('data/citations.json', {cache: 'no-cache'});
    if (!response.ok) throw new Error('data unavailable');
    const d = await response.json();
    const papers = d.publications.filter(p => Number.isInteger(p.year));
    const annual = [...d.annual].sort((a,b) => a.year-b.year);
    if (!papers.length || !annual.length) throw new Error('data unavailable');
    const years = [...new Set([...papers.map(p=>p.year), ...annual.map(a=>a.year)])].sort((a,b)=>a-b);
    const lo=years[0], hi=years[years.length-1];
    const x = year => 90 + (year-lo)/Math.max(1,hi-lo)*700;
    const maxBubble = Math.max(1,...papers.map(p=>p.citations));
    const leftMax = Math.max(5,Math.ceil(maxBubble/5)*5);
    let sum=0; const totals=annual.map(a=>({year:a.year, annual:a.citations, total:sum+=a.citations}));
    const rightMax = Math.max(10, Math.ceil(sum/10)*10);
    const yL = v => 295 - v/leftMax*235;
    const yR = v => 295 - v/rightMax*235;
    for(let i=0;i<=5;i++) {
      const y=295-i*47;
      element('line',{x1:90,y1:y,x2:790,y2:y,class:'chart-grid'});
      element('text',{x:76,y:y+4,'text-anchor':'end',class:'chart-tick'},String(Math.round(leftMax*i/5)));
      element('text',{x:805,y:y+4,class:'chart-tick'},String(Math.round(rightMax*i/5)));
    }
    element('text',{x:90,y:29,class:'chart-label'},'Citations per publication');
    element('text',{x:790,y:29,'text-anchor':'end',class:'chart-label'},'Cumulative citations');
    years.forEach(yr=>element('text',{x:x(yr),y:330,'text-anchor':'middle',class:'chart-tick'},String(yr)));
    element('text',{x:440,y:355,'text-anchor':'middle',class:'chart-tick'},'Publication year (bubbles) / citation year (line)');
    element('polyline',{points:totals.map(a=>`${x(a.year)},${yR(a.total)}`).join(' '),class:'chart-line'});
    totals.forEach(a=>{const c=element('circle',{cx:x(a.year),cy:yR(a.total),r:4.5,class:'chart-dot'});const t=document.createElementNS(ns,'title');t.textContent=`${a.year}: ${a.annual} citations; cumulative ${a.total}`;c.appendChild(t)});
    const group = new Map(); papers.forEach(p=>{let key=`${p.year}:${p.citations}`;let a=group.get(key)||[];a.push(p);group.set(key,a)});
    for (const same of group.values()) {
      const p = same[0];
      const c = element('circle', {
        cx:x(p.year), cy:yL(p.citations), r:8, class:'chart-bubble',
        tabindex:0, role:'button',
        'aria-label':`${same.length} publication${same.length === 1 ? '' : 's'}, ${p.year}, ${p.citations} citations: ${same.map(item => item.title).join('; ')}`
      });
      c.addEventListener('mouseenter',()=>show(same));
      c.addEventListener('mouseleave',()=>{tooltip.hidden=true});
      c.addEventListener('focus',()=>show(same));
      c.addEventListener('blur',()=>{tooltip.hidden=true});
      c.addEventListener('click',()=>select(same));
      c.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(same)}});
    }
    const missing=d.publications.length-papers.length;
    const date=new Date(d.updated_at).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
    note.textContent=`Source: ${d.source} · Updated ${date} · ${d.publications.length} entries · ${d.total_citations} total citations${missing ? ` · ${missing} entries without a publication year are not plotted` : ''}. The current year is incomplete; previous years reflect the latest index.`;
  } catch (_) {
    note.textContent='Citation data is temporarily unavailable. Please visit Google Scholar for the latest information.';
  }
})();
